-- Additive tables only. Existing phone and framework-owned tables are untouched.
CREATE TABLE IF NOT EXISTS peak_phone_jobs (id VARCHAR(48) COLLATE utf8mb4_bin PRIMARY KEY, definition MEDIUMTEXT NOT NULL, revision INT NOT NULL DEFAULT 1, updated_by VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, updated_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS peak_phone_job_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job_id VARCHAR(48) NOT NULL, actor VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, action VARCHAR(32) NOT NULL, revision INT NOT NULL, definition MEDIUMTEXT NOT NULL, created_at BIGINT NOT NULL, INDEX idx_job_audit(job_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS peak_phone_job_rewards (operation_id VARCHAR(100) COLLATE utf8mb4_bin PRIMARY KEY, run_id VARCHAR(80) NOT NULL, citizenid VARCHAR(128) COLLATE utf8mb4_bin NOT NULL, job_id VARCHAR(48) NOT NULL, amount INT UNSIGNED NOT NULL, account VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, INDEX idx_job_reward_owner(citizenid,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
